// Phân tích nội dung chuyển khoản để trích xuất Mã Đơn Hàng hoặc Bàn
// Format phổ biến: 'THANH TOAN BAN 01', 'DP-B01', 'MINI-123456', 'BAN 2'
const raw = $json.body || $json;
const content = (raw.description || raw.content || raw.transactionContent || '').toUpperCase();
const amount = raw.amount || raw.transferAmount || 0;
const bankAccount = raw.bankAccount || raw.accountNumber || '970422-MBBank';
const transId = raw.transactionId || raw.referenceNumber || Date.now().toString();

let matchedCode = 'KHÁCH LẺ';
const tableMatch = content.match(/BAN\s*(\d+|MANG\s*VE|VIP\d*)/i) || content.match(/DP-B(\d+)/i);
const miniMatch = content.match(/MINI-(\d+)/i);

if (tableMatch) {
  matchedCode = 'BÀN ' + tableMatch[1];
} else if (miniMatch) {
  matchedCode = 'ĐƠN ' + miniMatch[0];
}

return [{
  json: {
    transId: transId,
    amount: Number(amount),
    content: content,
    bankAccount: bankAccount,
    matchedCode: matchedCode,
    paidAt: new Date().toLocaleTimeString('vi-VN', { hour: '2-digit', minute: '2-digit', second: '2-digit' }),
    isMatched: matchedCode !== 'KHÁCH LẺ'
  }
}];
